import{_ as d}from"./chunks/path-hugo.CBIlszOp.js";import{_ as o,c as e,o as r,ag as c}from"./chunks/framework._xRlcm3f.js";const u=JSON.parse('{"title":"Hexo 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/common-github-hexo.md","filePath":"platforms/common-github-hexo.md","lastUpdated":1790228279000}'),a={name:"platforms/common-github-hexo.md"};function s(i,t,l,n,h,m){return r(),e("div",null,[...t[0]||(t[0]=[c('<h1 id="hexo-配置指南" tabindex="-1">Hexo 配置指南 <a class="header-anchor" href="#hexo-配置指南" aria-label="Permalink to &quot;Hexo 配置指南&quot;">​</a></h1><p>通过 <strong>GitHub API</strong> 将文章发布到 <strong>Hexo</strong> 静态博客仓库。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可作为 Hexo 博客仓库的 <strong>GitHub 仓库</strong>（如 <code>hexo-blog</code>）。</li><li>一个对该仓库有 <strong>push 权限</strong> 的 <strong>GitHub Token（PAT）</strong>（GitHub Settings → Developer settings → Personal access tokens，勾选 <code>repo</code> 权限）。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>首页地址</td><td>GitHub 首页地址，默认 <code>https://github.com</code></td></tr><tr><td>API 地址</td><td>GitHub API 地址，默认 <code>https://api.github.com</code>，通常无需修改</td></tr><tr><td>用户名</td><td>GitHub 用户名（owner），用于拼出仓库地址</td></tr><tr><td>鉴权 Token</td><td>GitHub 个人访问令牌（PAT），需对目标仓库有 push 权限</td></tr><tr><td>git 仓库名</td><td>Hexo 博客仓库名，与用户名组成 <code>&lt;user&gt;/&lt;repo&gt;</code>，如 <code>hexo-blog</code></td></tr><tr><td>默认分支</td><td>发布到的分支，默认 <code>main</code>，需与仓库实际分支一致</td></tr><tr><td>存储目录</td><td>Hexo 文章存储目录，默认 <code>source/_posts</code></td></tr><tr><td>文件规则</td><td>文章文件名规则，默认 <code>[filename].md</code></td></tr><tr><td>文章预览规则</td><td>站点文章预览规则，默认 <code>/post/[postid].html</code></td></tr><tr><td>预览规则</td><td>GitHub blob 预览规则，默认 <code>/[user]/[repo]/blob/[branch]/[docpath]</code></td></tr><tr><td>图床</td><td>Hexo 支持内置图床，选「当前平台」：图片上传到仓库 <code>source/images</code>（默认），文章引用为相对路径 <code>../images/&lt;图片名&gt;</code>，保证源码与构建产物都能显示</td></tr></tbody></table><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ Token、仓库、分支校验通过（会向仓库发布并清理测试文件）→ 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 Hexo → 发布。文章 <code>.md</code> 会提交到 <code>存储目录/文件名.md</code>。</li><li>点「查看文章」能看到该 <code>.md</code> 的 GitHub blob 地址；带图发布时图片会一并上传到仓库图床目录。</li></ol><h2 id="四、文件规则" tabindex="-1">四、文件规则 <a class="header-anchor" href="#四、文件规则" aria-label="Permalink to &quot;四、文件规则&quot;">​</a></h2><p>「文件规则」决定文章在仓库里的<strong>相对路径与文件名</strong>，默认 <code>[filename].md</code>。</p><p>可用占位符会动态替换：</p><table tabindex="0"><thead><tr><th>占位符</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td><code>[yyyy]</code></td><td>年</td><td><code>2025</code></td></tr><tr><td><code>[MM]</code></td><td>月</td><td><code>02</code></td></tr><tr><td><code>[mm]</code></td><td>月（不补零）</td><td><code>2</code></td></tr><tr><td><code>[dd]</code></td><td>日</td><td><code>26</code></td></tr><tr><td><code>[slug]</code></td><td>别名</td><td><code>test-document-xdfr45f</code></td></tr><tr><td><code>[filename]</code></td><td>文档真实标题</td><td><code>测试文档</code></td></tr><tr><td><code>[category]</code></td><td>第一个分类（没有则忽略）</td><td><code>技术</code></td></tr><tr><td><code>[cats]</code></td><td>全部分类组合</td><td><code>技术-笔记</code></td></tr><tr><td><code>[tag]</code></td><td>第一个标签（没有则忽略）</td><td><code>思源</code></td></tr><tr><td><code>[tags]</code></td><td>全部标签组合</td><td><code>思源-发布</code></td></tr></tbody></table><p>例如 <code>[yyyy]/[MM]/[filename].md</code>、<code>[slug].md</code>、<code>[yyyy]-[mm]-[dd]-[slug].md</code>。</p><div class="tip custom-block"><p class="custom-block-title">链接字符限制</p><p>路径中只允许 <code>/ - _ . ~</code>，其他字符会被移除。</p></div><h2 id="五、图片存储路径" tabindex="-1">五、图片存储路径 <a class="header-anchor" href="#五、图片存储路径" aria-label="Permalink to &quot;五、图片存储路径&quot;">​</a></h2><p>图床选「当前平台」时，可以指定图片存到仓库哪里：</p><p><img src="'+d+'" alt="填写图片存储目录与访问链接" loading="lazy"></p><table tabindex="0"><thead><tr><th>字段</th><th>Hexo 的默认值</th></tr></thead><tbody><tr><td>图片存储目录</td><td><code>source/images</code></td></tr><tr><td>图片访问链接</td><td><code>images</code></td></tr></tbody></table><p>两个值保持一致即可，一般不需要改。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证通过但发布失败</strong>：确认 Token 对目标仓库有 push 权限，仓库名与分支正确，存储目录已存在。权限不足会收到 401/403。</li><li><strong>图片要怎么发布</strong>：选「当前平台」图床，图片上传到仓库 <code>source/images</code>，文章中引用相对路径（源码编辑器与构建产物均可正常显示）。</li><li><strong>查看链接打不开</strong>：确认预览规则（默认 <code>/[user]/[repo]/blob/[branch]/[docpath]</code>）与文件路径、分支对应。</li><li><strong>「删除」和「解除关联」有什么区别</strong>：删除会<strong>先从平台移除文章</strong>，再解除本地记录；解除关联（界面上是「强制删除」）<strong>只解除关联</strong>，不动平台上的文章。文章在平台上被手动删掉后，用解除关联可以修复记录，便于重新发布。</li><li><strong>更新与删除</strong>：点「更新」会重新提交并产生一次新提交；「删除」会从仓库移除对应 <code>.md</code>，需重新发布才能再次出现在站点。</li></ul>',21)])])}const p=o(a,[["render",s]]);export{u as __pageData,p as default};
